import { IsNotEmpty, IsEmail, IsString, IsBoolean, IsOptional } from "class-validator";

export class UpdateUserDto {
    @IsOptional()
    @IsNotEmpty()
    @IsString()
    first_name: String;

    @IsOptional()
    @IsNotEmpty()
    @IsString()
    last_name: String;

    @IsOptional()
    @IsNotEmpty()
    @IsEmail()
    email: String;

    @IsOptional()
    @IsNotEmpty()
    @IsString()
    tax_code: String;

    @IsOptional()
    @IsNotEmpty()
    @IsString()
    password: String;

    @IsOptional()
    @IsNotEmpty()
    @IsBoolean()
    family_member: Boolean;

}
